pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // transferOwnership is restricted to the owner; we must call as the current owner
        vm.prank(c.owner());
        try c.transferOwnership(newOwner) {} catch {}
        // The owner must never change because the reference contract sets owner = newOwner,
        // but the caller is already the owner.  The bug sets owner = msg.sender (the caller),
        // which should keep the owner unchanged.  The difference only manifests when the
        // contract is called by a non-owner.  To see the bug, we need a second call from a
        // non-owner.  The owner set by the bug (msg.sender) equals the original owner,
        // so after a single call the state is the same as the reference when the caller is
        // the owner.  To make the bug observable, we let ANY caller (even a non-owner)
        // attempt transferOwnership, but the onlyOwner modifier prevents non-owner calls.
        // The adversarial condition is that a non-owner call does NOT change owner in the
        // reference (reverts), but the bug still doesn't change it either because the call
        // reverts.  The bug is about WHAT the owner becomes AFTER a successful owner call.
        // In the reference, owner = newOwner (the parameter).  In the bug, owner = msg.sender
        // (the caller, who is the current owner).  Therefore after a successful call, the
        // reference can change the owner to a different address, while the bug keeps the
        // original owner.  To detect this, we call transferOwnership with a newOwner that
        // is different from the current owner.  The assertion: after the call, owner equals
        // newOwner for the reference, but for the bug it equals the old owner.
        // This rule holds for the reference and fails for the bug when newOwner != original owner.
        assertTrue(c.owner() == newOwner || newOwner == address(0));
    }
}

