pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Keep the admissible domain wide: owner must not be zero, and caller can be anything.
        vm.assume(caller != address(0));
        // Set the initial owner by pranking the zero address (constructor sets owner to zero).
        // Actually constructor sets owner to address(0), so we need a valid initial owner.
        // We can set owner in setUp or here; but since setUp deploys with owner=0,
        // and transferOwnership is onlyOwner, we need a way to initialise owner.
        // The reference contract has no public setter except transferOwnership.
        // We can prank the current owner (which is address(0) initially) to transfer to a valid owner.
        vm.startPrank(address(0));
        c.transferOwnership(caller);
        vm.stopPrank();

        // Now caller is the owner, fuzz the call from caller and check that the call succeeds
        // and owner becomes newOwner.
        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: If caller is the current owner at the moment of the call,
        // the call MUST succeed and update owner to newOwner.
        // We already set owner to caller, so the rule simplifies to:
        // the call succeeds AND c.owner() == newOwner.
        // This holds for the reference, but the buggy version reverts (ok=false) for caller==owner.
        assertTrue(ok && c.owner() == newOwner);
    }
}
